"""The Pi tool-name transform, which the trajectory's correctness depends on.

τ's evaluator matches expected actions by tool name. If the reverse map is wrong, tool calls are
misattributed in the graded trajectory and the score changes without the evaluator being touched
— so these cases are pinned against values taken from the JS implementation
(`@introspection-ai/recipes/dist/mcp-tools.js`, `piMcpToolName`) rather than from our own output.
"""

from __future__ import annotations

import pytest

from tau_adapter.names import MAX_NAME_LEN, build_name_map, pi_mcp_tool_name

# Generated by the JS implementation with serverId "tau". Regenerate against upstream if
# Recipes changes the transform; do not "fix" a mismatch by editing these.
JS_REFERENCE = {
    "create_task": "mcp_tau_create_task_5cab118a37",
    "get_users": "mcp_tau_get_users_4751e9f472",
    "update_task_status": "mcp_tau_update_task_status_c6a55f73de",
    "transfer_to_human_agents": "mcp_tau_transfer_to_human_agents_ef54745fe2",
    "KB_search": "mcp_tau_KB_search_77c5623a9f",
    "get_current_time": "mcp_tau_get_current_time_38ed8300e7",
}


@pytest.mark.parametrize(("tau_name", "expected"), sorted(JS_REFERENCE.items()))
def test_matches_the_javascript_implementation(tau_name: str, expected: str) -> None:
    assert pi_mcp_tool_name("tau", tau_name) == expected


def test_preserves_case() -> None:
    # KB_search would collide with kb_search if the transform folded case.
    assert "KB_search" in pi_mcp_tool_name("tau", "KB_search")


def test_truncates_to_the_cap() -> None:
    long_name = "a-very-long-tool-name-that-definitely-exceeds-the-sixty-four-character-cap"
    assert len(pi_mcp_tool_name("tau", long_name)) == MAX_NAME_LEN


def test_map_inverts_the_transform() -> None:
    mapping = build_name_map("tau", list(JS_REFERENCE))
    for tau_name, pi_name in JS_REFERENCE.items():
        assert mapping[pi_name] == tau_name


def test_truncated_names_stay_distinguishable() -> None:
    """Two long names sharing a 53-character prefix must not collapse into one Pi name.

    They differ only past the truncation point, so the hash suffix is the only thing keeping
    them apart — exactly the case where a naive reverse parse would misattribute a tool call.
    """
    prefix = "identical_prefix_that_is_long_enough_to_be_truncated_"
    names = [f"{prefix}alpha", f"{prefix}beta"]
    mapping = build_name_map("tau", names)
    assert len(mapping) == 2


def test_collision_raises_rather_than_resolving() -> None:
    with pytest.raises(ValueError, match="both map to Pi name"):
        build_name_map("tau", ["get_users", "get_users"])
